import streamlit as st
import pandas as pd
import gspread
from google.oauth2.service_account import Credentials
import json, os

st.set_page_config(
    page_title="SNCIC · Panel de gestión",
    page_icon="🤝",
    layout="wide",
    initial_sidebar_state="collapsed"
)

SCOPES = ["https://www.googleapis.com/auth/spreadsheets","https://www.googleapis.com/auth/drive"]
HOJAS = {
    "espacios":        "espacios",
    "participantes":   "participantes",
    "fortalecimiento": "fortalecimiento_capacidades",
    "demanda":         "demanda_cooperacion",
    "articulacion":    "articulacion_institucional",
    "portafolio":      "Portafolio",
}

@st.cache_resource(ttl=300)
def get_client():
    creds = Credentials.from_service_account_info(st.secrets["gcp_service_account"], scopes=SCOPES)
    return gspread.authorize(creds)

@st.cache_data(ttl=120)
def leer_hoja(nombre):
    try:
        sh = get_client().open_by_key(st.secrets["gsheet_id"])
        data = sh.worksheet(nombre).get_all_records()
        return pd.DataFrame(data)
    except Exception:
        return pd.DataFrame()

def df_to_records(df):
    if df.empty: return []
    return df.fillna("").astype(str).to_dict(orient="records")

@st.cache_data(ttl=120)
def cargar_datos():
    return {
        "espacios":           df_to_records(leer_hoja(HOJAS["espacios"])),
        "participantes":      df_to_records(leer_hoja(HOJAS["participantes"])),
        "fortalecimiento":    df_to_records(leer_hoja(HOJAS["fortalecimiento"])),
        "demanda":            df_to_records(leer_hoja(HOJAS["demanda"])),
        "articulacion":       df_to_records(leer_hoja(HOJAS["articulacion"])),
        "portafolio":         df_to_records(leer_hoja(HOJAS["portafolio"])),
        "demanda_analisis":   df_to_records(leer_hoja("demanda_analisis")),
    }

def leer_geojson():
    for p in ["Colombia.geo.json", "Colombia_geo.json", "/app/Colombia.geo.json"]:
        if os.path.exists(p):
            with open(p, "r", encoding="utf-8") as f:
                geo = json.load(f)
            def simplify(coords):
                if isinstance(coords[0], list): return [simplify(c) for c in coords]
                return [round(coords[0], 4), round(coords[1], 4)]
            for feat in geo["features"]:
                geom = feat["geometry"]
                if geom["type"] == "Polygon":
                    geom["coordinates"] = [simplify(r) for r in geom["coordinates"]]
                elif geom["type"] == "MultiPolygon":
                    geom["coordinates"] = [[simplify(r) for r in p] for p in geom["coordinates"]]
                p2 = feat["properties"]
                feat["properties"] = {
                    "DPTO": str(p2.get("DPTO","")).lstrip("0"),
                    "NOMBRE_DPT": p2.get("NOMBRE_DPT", p2.get("nombre",""))
                }
            return json.dumps(geo, separators=(',', ':'))
    return "null"

def generar_panel():
    data = cargar_datos()
    geo_str = leer_geojson()
    for p in ["panel_sncic.html", "/app/panel_sncic.html"]:
        if os.path.exists(p):
            with open(p, "r", encoding="utf-8") as f:
                template = f.read()
            # En el panel público ocultamos el header del HTML
            # y mostramos nuestro propio header con logos via Streamlit
            template = template.replace("</style>", ".header{display:none!important;}</style>")
            return (template
                .replace("__PANEL_DATA__", json.dumps(data, ensure_ascii=False))
                .replace("__COLOMBIA_GEO__", geo_str))
    return "<h1>Template no encontrado</h1>"

